from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Return the sum of x*x over every element of xs.

    The squares are computed in parallel with a thread pool, using
    `square`. The result is exact (integer arithmetic) and does not
    depend on the number of workers or on the order in which tasks
    finish. An empty list gives 0. The input list is not modified.
    """
    if not xs:
        return 0
    with ThreadPoolExecutor() as pool:
        return sum(pool.map(square, xs))


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49
    assert sum_squares([0]) == 0


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_negatives() -> None:
    assert sum_squares([-1, -2, -3]) == 14
    assert sum_squares([-5, 5]) == 50


def test_large_ints_exact() -> None:
    big = 10**12
    assert sum_squares([big, -big, 1]) == 2 * big * big + 1


def test_matches_sequential_on_large_input() -> None:
    xs = list(range(-5000, 5000))
    assert sum_squares(xs) == sum(x * x for x in xs)


def test_repeated_calls_are_identical() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(2000)]
    expected = sum(x * x for x in xs)
    results = {sum_squares(xs) for _ in range(20)}
    assert results == {expected}


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 4, 1, -5]
    copy = list(xs)
    sum_squares(xs)
    assert xs == copy


def test_duplicates_and_order_irrelevant() -> None:
    xs = [2, 2, 3, -3, 1]
    assert sum_squares(xs) == 27
    assert sum_squares(list(reversed(xs))) == 27
    assert sum_squares(sorted(xs)) == 27


def test_concurrent_callers_agree() -> None:
    xs = list(range(1, 501))
    expected = sum(x * x for x in xs)
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = [pool.submit(sum_squares, xs) for _ in range(16)]
        assert [f.result() for f in futures] == [expected] * 16
